UPDATE fgc.validation_run
   SET status = #{newStatus}
 WHERE validation_run_id = #{validationRunId}
   AND status = #{expectedStatus}

mapper.select:
SELECT COALESCE(MAX(run_no), 0) + 1
  FROM fgc.validation_run
 WHERE validation_month = #{validationMonth}

mapper.update:
UPDATE fgc.validation_run
   SET current_step = #{currentStep}
 WHERE validation_run_id = #{validationRunId}
   AND status = 'RUNNING'
   AND current_step <= #{currentStep}

UPDATE fgc.validation_run
   SET status = 'FAILED',
       current_step = #{currentStep},
       failure_message = #{failureMessage}
 WHERE validation_run_id = #{validationRunId}
   AND status = 'RUNNING'
   AND current_step <= #{currentStep}
